SQLitePCL.Batteries_V2.Init();Store.Init();
var builder=WebApplication.CreateBuilder(args);var app=builder.Build();
app.Use(async(context,next)=>{if(context.Request.Path=="/health"){await next();return;}var token=context.Request.Headers.Authorization.ToString();if(token!="Bearer test-alice"&&token!="Bearer test-bob"){context.Response.StatusCode=401;return;}context.Items["owner"]=token[12..];await next();});
app.MapGet("/health",()=>Results.Ok());
app.MapGet("/tickets",(HttpContext ctx)=>{using var c=Store.Open();using var q=Store.Cmd(c,"SELECT id,title,status,version FROM tickets WHERE owner=@owner ORDER BY id",("@owner",ctx.Items["owner"]!));using var r=q.ExecuteReader();var rows=new List<Ticket>();while(r.Read())rows.Add(Store.Read(r));return Results.Ok(new {items=rows});});
app.MapPost("/tickets",(HttpContext ctx,CreateTicket input)=>{var title=input.Title?.Trim();if(title is null||title.Length<1||title.Length>80)return Results.BadRequest();using var c=Store.Open();using var q=Store.Cmd(c,"INSERT INTO tickets(owner,title,status,version) VALUES(@owner,@title,'open',1) RETURNING id,title,status,version",("@owner",ctx.Items["owner"]!),("@title",title));using var r=q.ExecuteReader();r.Read();return Results.Json(Store.Read(r),statusCode:201);});
app.MapPatch("/tickets/{id:long}",(HttpContext ctx,long id,UpdateTicket input)=>{if(input.Status is not ("open" or "in-progress" or "done")||input.Version<1)return Results.BadRequest();using var c=Store.Open();using var q=Store.Cmd(c,"UPDATE tickets SET status=@status,version=version+1 WHERE id=@id AND owner=@owner AND version=@version RETURNING id,title,status,version",("@status",input.Status),("@id",id),("@owner",ctx.Items["owner"]!),("@version",input.Version));using(var r=q.ExecuteReader()){if(r.Read())return Results.Ok(Store.Read(r));}using var lookup=Store.Cmd(c,"SELECT COUNT(*) FROM tickets WHERE id=@id AND owner=@owner",("@id",id),("@owner",ctx.Items["owner"]!));return Convert.ToInt32(lookup.ExecuteScalar())==0?Results.NotFound():Results.Conflict();});
app.Run("http://127.0.0.1:8080");
